package org.acme.legacy;

public class ConfigParser {
    public java.util.Map<String, String> defaults() {
        java.util.Map<String, String> values = new java.util.HashMap<String, String>();
        values.put("timeout", "30");
        return values;
    }
}

package org.acme.legacy;

import org.junit.Test;

import static org.junit.Assert.*;

public class ConfigParserTest {
    @Test
    public void readsDefaults() {
        assertEquals("30", new ConfigParser().defaults().get("timeout"));
    }
}

